#!/bin/sh
# Schema init job for MySQL/MariaDB: loads the Guacamole schema if it is missing, checks the schema
# version of an existing database and secures the guacadmin account. Idempotent.
#
# Environment:
#   DB_HOST, DB_PORT, DB_NAME, DB_USER, DB_PASSWORD  connection
#   ADMIN_PASSWORD     password for guacadmin
#   ENFORCE_PASSWORD   "true" sets the password on every run
#   SCHEMA_FILE        SQL generated by initdb.sh
#   WAIT_TIMEOUT       seconds to wait for the database
set -eu

log() { echo "[schema-init] $*"; }
die() { echo "[schema-init] ERROR: $*" >&2; exit 1; }

[ -n "${ADMIN_PASSWORD:-}" ] || die "admin password is empty"

# Prefer the mariadb client, fall back to mysql (both read the option file below).
if command -v mariadb >/dev/null 2>&1; then CLIENT=mariadb; else CLIENT=mysql; fi

# Credentials go into an option file instead of the command line. Values are double-quoted,
# so backslashes and double quotes are escaped.
escape() { printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'; }
OPTIONS_FILE=/tmp/client.cnf
umask 077
cat > "$OPTIONS_FILE" <<CNF
[client]
host="$(escape "$DB_HOST")"
port=$DB_PORT
user="$(escape "$DB_USER")"
password="$(escape "$DB_PASSWORD")"
database="$(escape "$DB_NAME")"
# Like the default JDBC mode "preferred": use TLS if offered, without verifying the certificate.
[client-mariadb]
ssl-verify-server-cert=0
CNF

sql() { "$CLIENT" --defaults-extra-file="$OPTIONS_FILE" "$@"; }
query() { sql -N -B -e "$1"; }
# Hex-encodes a string so it can be embedded in SQL without quoting issues.
hex() { printf '%s' "$1" | od -An -tx1 | tr -d ' \n'; }

log "waiting for the database at ${DB_HOST}:${DB_PORT} (timeout ${WAIT_TIMEOUT}s)"
elapsed=0
until query "SELECT 1" >/dev/null 2>&1; do
    [ "$elapsed" -lt "$WAIT_TIMEOUT" ] || { query "SELECT 1" || true; die "database not reachable after ${WAIT_TIMEOUT}s"; }
    sleep 5
    elapsed=$((elapsed + 5))
done

initialized=false
if [ "$(query "SELECT COUNT(*) FROM information_schema.TABLES
               WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'guacamole_user'")" = "0" ]; then
    log "schema not found, loading it"
    sql < "$SCHEMA_FILE"
    initialized=true
    log "schema loaded"
else
    # Guacamole 1.6.0 added the AUDIT system permission (upgrade-pre-1.6.0.sql).
    has_audit="$(query "SELECT COUNT(*) FROM information_schema.COLUMNS
                        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'guacamole_system_permission'
                          AND COLUMN_NAME = 'permission' AND COLUMN_TYPE LIKE '%''AUDIT''%'")"
    [ "$has_audit" = "1" ] || die "existing schema is older than 1.6.0. Upgrade it manually with
    upgrade-pre-1.6.0.sql (see /opt/guacamole/extensions/guacamole-auth-jdbc/mysql/schema/upgrade/
    in the guacamole image) and run the upgrade again."
    log "schema exists and matches version 1.6"
fi

is_default="$(query "SELECT COUNT(*) FROM guacamole_user u JOIN guacamole_entity e ON e.entity_id = u.entity_id
                     WHERE e.name = 'guacadmin' AND e.type = 'USER'
                       AND u.password_hash = UNHEX(SHA2(CONCAT('guacadmin', HEX(u.password_salt)), 256))")"

if [ "$initialized" = "true" ] || [ "$ENFORCE_PASSWORD" = "true" ] || [ "$is_default" = "1" ]; then
    updated="$(query "SET @salt = UNHEX(SHA2(CONCAT(UUID(), RAND()), 256));
                      SET @password = CONVERT(UNHEX('$(hex "$ADMIN_PASSWORD")') USING utf8mb4);
                      UPDATE guacamole_user u JOIN guacamole_entity e ON e.entity_id = u.entity_id
                      SET u.password_salt = @salt,
                          u.password_hash = UNHEX(SHA2(CONCAT(@password, HEX(@salt)), 256)),
                          u.password_date = NOW()
                      WHERE e.name = 'guacadmin' AND e.type = 'USER';
                      SELECT ROW_COUNT();")"
    if [ "$updated" = "1" ]; then
        log "guacadmin password set from Secret"
    else
        log "user guacadmin does not exist, nothing to secure"
    fi
else
    log "guacadmin password was changed already, leaving it untouched"
fi

log "done"
